// Общее для окна установки PWA «אל תחמיצו אף הזדמנות» (specs/pwa-install-prompt.md, #631293, #81a046).
// Прод, только просмотр. Не-GET запросы обрываются, кроме:
//  - POST rest/v1/rpc/pwa_app_last_opened — чтение «когда приложение открывалось» по cookie b4s_device; без его ответа
//    окно на iOS не показывается вовсе (не мокается — настоящий ответ, на ручной проверке 200 «null»);
//  - /auth/v1/ (продление входа) — только для вошедшего (keepAuth).
// Время: таймер окна — setTimeout 3000 мс после выполнения условий; вместо ожидания используется page.clock (install + runFor).
import { expect, BrowserContext, Page } from '@playwright/test';

export const LOAD = { timeout: 30_000 };
export const DISMISSED_KEY = 'b4s_install_prompt_dismissed_at';
export const IOS_STEPS_KEY = 'b4s_install_prompt_ios_steps_seen_at';
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const RPC = '/rest/v1/rpc/pwa_app_last_opened';

/** Вызывать до первого перехода. Cookie-баннер не трогает — выбор делает тест кнопкой «חיוניים בלבד». */
export async function prepareReadOnly(context: BrowserContext, keepAuth = false) {
  await context.route('**/*', (route) => {
    const req = route.request();
    if (SAFE_METHODS.includes(req.method()) || req.url().includes(RPC) || (keepAuth && req.url().includes('/auth/v1/'))) {
      return route.fallback();
    }
    return route.abort('blockedbyclient');
  });
}

/** Ответ RPC pwa_app_last_opened (условие показа на iOS). Подписаться ДО page.goto. */
export const rpcResponse = (page: Page) =>
  page.waitForResponse((r) => r.url().includes(RPC), LOAD);

export const installDialog = (page: Page) => page.getByText('אל תחמיצו אף הזדמנות');
export const laterButton = (page: Page) => page.getByRole('button', { name: 'אולי מאוחר יותר' });

/** Баннер cookie → «חיוניים בלבד» (как в шагах тикета). */
export async function chooseEssentialCookies(page: Page) {
  await page.getByRole('button', { name: 'חיוניים בלבד' }).click(LOAD);
  await expect
    .poll(() => page.evaluate(() => localStorage.getItem('cookie-consent-v2')), { message: 'выбор cookie сохранён', ...LOAD })
    .not.toBeNull();
}

export const storageKey = (page: Page, key: string) => page.evaluate((k) => localStorage.getItem(k), key);
